/// Detect conflicts between I002 (missing-required-import) and PYI025
/// (unaliased-collections-abc-set-import).
///
/// PYI025 requires `from collections.abc import Set` to be aliased as `AbstractSet`, so requiring
/// the unaliased form via `lint.isort.required-imports` while PYI025 is enabled is contradictory.
fn conflicting_required_import_set_alias(
    isort: &isort::settings::Settings,
    rules: &RuleTable,
) -> Result<()> {
    if !rules.enabled(Rule::UnaliasedCollectionsAbcSetImport) {
        return Ok(());
    }

    let has_unaliased_set = isort.required_imports.iter().any(|required_import| {
        required_import.qualified_name().to_string() == "collections.abc.Set"
            && required_import.bound_name() == "Set"
    });

    if has_unaliased_set {
        return Err(anyhow!(
            "Required import `from collections.abc import Set` specified in `lint.isort.required-imports` (I002) conflicts with `unaliased-collections-abc-set-import` (PYI025), which requires this import to be aliased as `AbstractSet`.\n\
            Help: Either alias the required import (`from collections.abc import Set as AbstractSet`), or disable PYI025."
        ));
    }

    Ok(())
